def ofdm_tx(bits, n_sub, cp_len):
    syms = qam_map(bits)  # 비트 → 복소 심볼
    out = []
    for i in range(0, len(syms), n_sub):
        X = syms[i:i + n_sub]  # 부반송파마다 1심볼(병렬)
        x = ifft(X)  # 주파수 → 시간 영역
        out += x[-cp_len:] + x  # CP: 꼬리를 앞에 복사
    return out

def ofdm_rx(samples, n_sub, cp_len):
    syms, step = [], n_sub + cp_len
    for i in range(0, len(samples), step):
        y = samples[i + cp_len:i + step]  # CP 제거
        Y = fft(y)
        syms += equalize(Y)  # 부반송파별 1탭 등화
    return qam_demap(syms)
